3	const mineflayer = require('mineflayer')
4	const { pathfinder, Movements } = require('mineflayer-pathfinder')
5	const { makeBrain } = require('./brain')
6	const { findTarget, buildState, stateKey } = require('./perception')
7	const { makeScout, findNearest } = require('./behaviours/scout')
8	
9	const BEHAVIOURS = {
10	  fight: require('./behaviours/fight'),
11	  follow: require('./behaviours/follow'),
12	  roam: require('./behaviours/roam'),
13	}
14	
15	// Poll cadence when nobody is online: no JEV calls happen there, so waking
16	// up every 10 s just to re-scan the player list is plenty.
17	const IDLE_TICK_MS = 10000
18	const IDLE_LOG_MS = 60000
19	
20	function createTicker({ bot, brain, tickMs = 1000, idleTickMs = IDLE_TICK_MS, followName = '' }) {
21	  const ctx = { lastGoalKey: '', movements: null, paused: false }
22	  let inFlight = false
23	  let lastTargetPos = null
24	  let lastVisible = true
25	  let lastIdleLog = 0
26	  let lastStateKey = null
27	  let lastDecision = null
28	
29	  function applyDecision(decision, target, state) {
30	    const handler = BEHAVIOURS[decision.action]
31	    if (typeof handler === 'function') {
32	      handler(bot, ctx, target, state)
33	    } else {
34	      if (ctx.lastGoalKey !== 'idle') bot.pathfinder.stop()
35	      ctx.lastGoalKey = 'idle'
36	    }
37	    if (ctx.movements) ctx.movements.allowSprinting = !!decision.sprint
38	    const dist = typeof state.distance_to_player === 'number' ? state.distance_to_player.toFixed(1) : 'none'
39	    console.log(`decision source=${decision.source} action=${decision.action} sprint=${decision.sprint} dist=${dist}`)
40	  }
41	
42	  function scheduleNext(fast) {
43	    const t = setTimeout(() => { void tick() }, fast ? tickMs : idleTickMs)
44	    if (t && typeof t.unref === 'function') t.unref()
45	  }
46	
47	  async function tick() {
48	    if (inFlight) { scheduleNext(lastVisible); return { decision: null, calledBrain: false } }
49	    inFlight = true
50	    let calledBrain = false
51	    try {
52	      if (ctx.paused) {
53	        // 'stop' parks the bot: perception + scout keep running while a
54	        // player is visible, but the brain is skipped and idle is dispatched
55	        // (stop once) — same cost guard as 'no player online', including no
56	        // scans with nobody online.
57	        const target = findTarget(bot, followName)
58	        lastVisible = !!target
59	        if (target) {
60	          const state = buildState(bot, target, lastTargetPos)
61	          lastTargetPos = state._lastTargetPos
62	          if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
63	          if (ctx.scout) ctx.scout.tick()
64	        } else {
65	          lastTargetPos = null
66	          lastDecision = null
67	          lastStateKey = null
68	        }
69	        if (ctx.lastGoalKey !== 'idle') {
70	          bot.pathfinder.stop()
71	          ctx.lastGoalKey = 'idle'
72	        }
73	        const now = Date.now()
74	        if (now - lastIdleLog >= IDLE_LOG_MS) {
75	          lastIdleLog = now
76	          console.log('decision source=local-idle action=idle sprint=false dist=none')
77	        }
78	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
79	      }
80	      const target = findTarget(bot, followName)
81	      lastVisible = !!target
82	      if (!target) {
83	        // Cost fix: nobody online => no brain call at all, decide idle
84	        // locally, stop once, and stay quiet (at most one line per minute).
85	        if (ctx.lastGoalKey !== 'idle') {
86	          bot.pathfinder.stop()
87	          ctx.lastGoalKey = 'idle'
88	        }
89	        lastTargetPos = null
90	        lastDecision = null
91	        lastStateKey = null
92	        const now = Date.now()
93	        if (now - lastIdleLog >= IDLE_LOG_MS) {
94	          lastIdleLog = now
95	          console.log('decision source=local-idle action=idle sprint=false dist=none')
96	        }
97	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
98	      }
99	      const state = buildState(bot, target, lastTargetPos)
100	      lastTargetPos = state._lastTargetPos
101	      // every-tick hooks (no body cost) go here
102	      if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
103	      if (ctx.scout) ctx.scout.tick()
104	      const key = stateKey(state)
105	      let decision
106	      if (lastDecision && key === lastStateKey) {
107	        decision = lastDecision
108	      } else {
109	        decision = await brain.decide(state)
110	        calledBrain = true
111	        // A stub-fallback means JEV failed; don't cache it or JEV would
112	        // never be retried while the player stands still.
113	        if (decision.source !== 'stub-fallback') {
114	          lastStateKey = key
115	          lastDecision = decision
116	        }
117	      }
118	      if (ctx.paused) {
119	        // 'stop' landed during the brain await: discard the stale decision
120	        // so one in-flight tick cannot issue a follow goal after the park.
121	        if (ctx.lastGoalKey !== 'idle') {
122	          bot.pathfinder.stop()
123	          ctx.lastGoalKey = 'idle'
124	        }
125	        const now = Date.now()
126	        if (now - lastIdleLog >= IDLE_LOG_MS) {
127	          lastIdleLog = now
128	          console.log('decision source=local-idle action=idle sprint=false dist=none')
129	        }
130	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain }
131	      }
132	      applyDecision(decision, target, state)
133	      return { decision, calledBrain }
134	    } catch (err) {
135	      console.error(`tick error: ${err && err.message ? err.message : err}`)
136	      return { decision: null, calledBrain }
137	    } finally {
138	      inFlight = false
139	      scheduleNext(lastVisible)
140	    }
141	  }
142	
143	  return {
144	    tick,
145	    start: () => scheduleNext(true),
146	    setMovements: (m) => { ctx.movements = m; bot.pathfinder.setMovements(m) },
